package com.dy.artisan3d.ui.componentimport androidx.compose.runtime.*import androidx.compose.ui.Modifierimport androidx.compose.ui.interop.UIKitViewimport kotlinx.cinterop.ExperimentalForeignApiimport kotlinx.cinterop.readValueimport platform.CoreGraphics.CGRectZeroimport platform.Foundation.NSErrorimport platform.Foundation.NSURLimport platform.Foundation.NSURLRequestimport platform.UIKit.UIColorimport platform.WebKit.*import platform.darwin.NSObject@OptIn(ExperimentalForeignApi::class)@Composableactual fun ModelViewer(    modelUrl: String,    siteUrl: String,    modifier: Modifier,    autoRotate: Boolean,    enableZoom: Boolean,    enablePan: Boolean,    onLoaded: () -> Unit,    onError: (String) -> Unit,) {    // WebView delegate class    class WebViewDelegate : NSObject(), WKNavigationDelegateProtocol {        var onLoadedCallback: (() -> Unit)? = null        var onErrorCallback: ((String) -> Unit)? = null        override fun webView(            webView: WKWebView,            didFinishNavigation: WKNavigation?        ) {            onLoadedCallback?.invoke()        }    }    val delegate = remember {        WebViewDelegate().apply {            onLoadedCallback = onLoaded            onErrorCallback = onError        }    }    UIKitView(        factory = {            // Configuration            val config = WKWebViewConfiguration()            config.allowsInlineMediaPlayback = true            config.mediaTypesRequiringUserActionForPlayback = WKAudiovisualMediaTypeNone            // Create WebView            val webView = WKWebView(frame = CGRectZero.readValue(), configuration = config)            webView.navigationDelegate = delegate            webView.scrollView.scrollEnabled = enablePan            webView.scrollView.bounces = true            webView.backgroundColor = UIColor.whiteColor            // Zoom sozlamalari            if (enableZoom) {                webView.scrollView.minimumZoomScale = 0.5                webView.scrollView.maximumZoomScale = 5.0            } else {                webView.scrollView.minimumZoomScale = 1.0                webView.scrollView.maximumZoomScale = 1.0            }            // URL ni yuklash            val url = NSURL.URLWithString(siteUrl)            if (url != null) {                val request = NSURLRequest.requestWithURL(url)                webView.loadRequest(request)            } else {                onError("URL xato")            }            webView        },        modifier = modifier,        update = { webView ->            webView.scrollView.scrollEnabled = enablePan            if (enableZoom) {                webView.scrollView.minimumZoomScale = 0.5                webView.scrollView.maximumZoomScale = 5.0            } else {                webView.scrollView.minimumZoomScale = 1.0                webView.scrollView.maximumZoomScale = 1.0            }        }    )}actual fun isModelViewerSupported(): Boolean = trueactual fun getSupportedModelFormats(): List<String> = listOf("glb", "gltf", "usdz")